set -euo pipefail
cd /home/ubuntu/apps/travel-planner
.venv/bin/python - <<'PY'
from pathlib import Path
import json,base64,hashlib
payload=json.loads('{"rag/eval/runners/audit_entity_uniqueness.py": "", "rag/eval/reports/entity_core_uniqueness.json": "", "rag/eval/reports/entity_core_uniqueness.md": "", "rag/eval/catalog/routing.md": "", "rag/eval/catalog/inventory.json": ""}')
for n,b in payload.items():
 p=Path(n);data=base64.b64decode(b);p.write_bytes(data);assert hashlib.sha256(p.read_bytes()).hexdigest()==hashlib.sha256(data).hexdigest()
print('Synced 5 audit files; runtime service unchanged')
PY
